/**
 * @file src/lib/rocketCasinoLogic.ts
 * Pure casino symbol/reward helpers (no DOM).
 */

import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.js';
import { ROCKET_CASINO_CONFIG } from '../../constants/balance/teamRocket.js';
import { uiText, uiIsEn, uiTitleCaseFromKeyEn, uiMaybeLocalizeItemName } from '../ui/i18n.ts';
import type { GameRuntime } from '../types/game.js';
import { game } from '../../gameManager.ts';
import { getAllItem } from '../ui/uiItems.ts';

const ROCKET_CASINO_SYMBOL_KEY_LEGACY: Record<string, string> = { logo_r: 'red_gyarados' };
const ROCKET_CASINO_SYMBOL_LABELS_EN: Record<string, string> = {
  zubat: 'Zubat',
  koffing: 'Koffing',
  arbok: 'Arbok',
  red_gyarados: 'Red Gyarados',
  meowth: 'Meowth',
  giovanni: 'Giovanni',
};

function uiGameRef(ref: GameRuntime | null | undefined): GameRuntime | undefined {
  return ref ?? undefined;
}

export interface RocketCasinoReward {
  rewardType?: string;
  targetId?: string;
  amount?: number;
}

export function getRocketCasinoSymbolMeta(
  symbolKey: string,
  gameRef: GameRuntime | null | undefined = game,
) {
  const resolvedKey = ROCKET_CASINO_SYMBOL_KEY_LEGACY[symbolKey] ?? symbolKey;
  const cfg = Array.isArray(ROCKET_CASINO_CONFIG.symbols) ? ROCKET_CASINO_CONFIG.symbols : [];
  const symbol = cfg.find((s) => s.key === resolvedKey);
  if (!symbol) {
    const fallbackLabel = resolvedKey || symbolKey || 'Inconnu';
    const label = uiIsEn(uiGameRef(gameRef)) ? uiTitleCaseFromKeyEn(fallbackLabel) : fallbackLabel;
    return { key: resolvedKey || symbolKey || 'unknown', id: 'N/A', label, sprite: '', payMultiplier: 0 };
  }
  const baseLabel = symbol.label || symbol.key;
  const label = uiIsEn(uiGameRef(gameRef))
    ? ROCKET_CASINO_SYMBOL_LABELS_EN[symbol.key] || uiTitleCaseFromKeyEn(symbol.key || baseLabel)
    : baseLabel;
  return {
    key: symbol.key,
    id: symbol.id || symbol.key,
    label,
    sprite: symbol.sprite || '',
    payMultiplier: Number(symbol.payMultiplier) || 0,
  };
}

export function getRocketCasinoRewardSprite(
  reward: RocketCasinoReward | null | undefined,
  gameRef: GameRuntime | null | undefined = game,
) {
  if (!reward || !reward.rewardType) return { src: '', alt: '', label: '', icon: undefined as string | undefined };
  const t = String(reward.rewardType);
  const id = String(reward.targetId || '');
  if (t === 'currency') {
    if (id === 'marques_du_triomphe') {
      const alt = uiText('teamRocket.rewardMarks', 'Triumph Marks', {}, uiGameRef(gameRef));
      return {
        src: 'https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png',
        alt,
        label: alt,
      };
    }
    if (id === 'essence_dust') {
      const alt = uiText('teamRocket.rewardDust', 'Essence dust', {}, uiGameRef(gameRef));
      return { src: 'https://raw.githubusercontent.com/msikma/pokesprite/master/items/medicine/energy-powder.png', alt, label: alt };
    }
    if (id === 'pokedollars_scaled' || id === 'pokedollars') {
      return {
        src: 'img/pokedollars.png',
        alt: uiText('teamRocket.rewardPokedollars', 'Pokedollars', {}, uiGameRef(gameRef)),
        label: '$',
      };
    }
  }
  if (t === 'quest_token') {
    const alt = uiText('teamRocket.rewardTokens', 'Quest Tokens', {}, uiGameRef(gameRef));
    return {
      src: 'https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png',
      alt,
      label: alt,
    };
  }
  if (t === 'jackpot') {
    const symbols = ROCKET_CASINO_CONFIG.symbols ?? [];
    const meowth = symbols.find((s) => (s.key || '').toString() === 'meowth');
    return {
      src:
        meowth && meowth.sprite
          ? meowth.sprite
          : 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-v/black-white/52.png',
      alt: uiText('teamRocket.rewardJackpotMeowth', 'Meowth Jackpot', {}, uiGameRef(gameRef)),
      label: uiText('teamRocket.rewardJackpot', 'Jackpot', {}, uiGameRef(gameRef)),
    };
  }
  if (t === 'item' && ALL_ITEMS) {
    const item = getAllItem(id) ?? (id.startsWith('ct_') ? { name: 'CT ' + id.replace('ct_', ''), icon: 'CT' } : null);
    if (item) {
      const displayName = uiMaybeLocalizeItemName(gameRef ?? null, item, id, item.name || id);
      return { src: item.img || '', alt: displayName, label: displayName, icon: item.icon };
    }
  }
  return { src: '', alt: id || t, label: id || t, icon: 'OBJ' };
}

export function isRocketCasinoFullBoard(
  winningLines: ReadonlyArray<{ coords?: ReadonlyArray<[number, number]> }>,
): boolean {
  const covered = new Set<string>();
  for (const win of winningLines) {
    for (const [row, col] of win.coords ?? []) {
      covered.add(`${row},${col}`);
    }
  }
  return covered.size === 9;
}

export function rollRocketCasinoSymbolKey(): string | null {
  const cfg = Array.isArray(ROCKET_CASINO_CONFIG.symbols) ? ROCKET_CASINO_CONFIG.symbols : [];
  if (cfg.length === 0) return null;
  const totalWeight = cfg.reduce((sum, s) => sum + Math.max(0, Number(s.weight) || 0), 0) || 1;
  let r = Math.random() * totalWeight;
  for (const s of cfg) {
    const w = Math.max(0, Number(s.weight) || 0);
    if (r < w) return s.key;
    r -= w;
  }
  return cfg[0]?.key ?? 'unknown';
}
